// Test-only sealer that mirrors the app's QSCryptionManager.encryptDataRecipient for the external ML-KEM-768
// recipient. All randomness is passed in, so a vector can be regenerated byte for byte. The X-Wing recipient is a
// placeholder: the CLI never reads it, and node has no X-Wing implementation.

const crypto = require('crypto');
const { ml_kem768 } = require('@noble/post-quantum/ml-kem.js');
const { envelopeAuthenticatedData } = require('../../scripts/utils/shared-definitions');

const b64 = (buf) => Buffer.from(buf).toString('base64');

function kidFor(publicKey) {
    return 'mlkem768:' + crypto.createHash('sha256').update(publicKey).digest().subarray(0, 8).toString('hex');
}

function aesGcmSeal(key, nonce, plaintext, aad) {
    const cipher = crypto.createCipheriv('aes-256-gcm', key, nonce);
    cipher.setAAD(aad);
    const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
    return { ciphertext, tag: cipher.getAuthTag() };
}

/**
 * @returns {{envelope: object, wrappedK: Buffer}} the full envelope (wrappedK included) and the external wrappedK
 */
function sealEnvelope({ plaintext, context, mlkemPublicKey, randomness, fileType }) {
    const { contentKey, payloadNonce, encapsulationSeed, salt, wrapNonce, xwingPlaceholder } = randomness;

    const content = aesGcmSeal(contentKey, payloadNonce, plaintext, envelopeAuthenticatedData(context));

    const { cipherText: kemCt, sharedSecret } = ml_kem768.encapsulate(mlkemPublicKey, encapsulationSeed);
    const kid = kidFor(mlkemPublicKey);
    const kek = Buffer.from(crypto.hkdfSync('sha256', Buffer.from(sharedSecret), salt, Buffer.from(`wrap|v=1|kid=${kid}|alg=AES-256-GCM`), 32));
    const kemHash = b64(crypto.createHash('sha256').update(kemCt).digest());
    const wrapAAD = Buffer.from(`recV=1|kid=${kid}|type=mlkem768|kem_hash=${kemHash}|nonce=${b64(wrapNonce)}`, 'utf8');
    const wrapped = aesGcmSeal(kek, wrapNonce, contentKey, wrapAAD);
    const wrappedK = Buffer.concat([wrapNonce, wrapped.ciphertext, wrapped.tag]);

    const envelope = {
        version: 2,
        algorithm: 'X-Wing/ML-KEM-768 + AES-256-GCM',
        ciphertext: b64(content.ciphertext),
        nonce: b64(payloadNonce),
        tag: b64(content.tag),
        recipients: [
            { recV: 1, type: 'xwing', kid: 'xwing:0000000000000000', kem_ct: b64(xwingPlaceholder), salt: b64(salt), wrappedK: b64(xwingPlaceholder) },
            { recV: 1, type: 'mlkem768', kid, kem_ct: b64(kemCt), salt: b64(salt), wrappedK: b64(wrappedK) }
        ]
    };
    if (fileType !== undefined) envelope.fileType = fileType;
    return { envelope, wrappedK };
}

/** The copy uploaded to Arweave: the external recipient's wrappedK is emptied, as in prepareForArweaveStorage. */
function forArweave(envelope) {
    return {
        ...envelope,
        recipients: envelope.recipients.map((r) => (r.type === 'mlkem768' ? { ...r, wrappedK: '' } : r))
    };
}

module.exports = { sealEnvelope, forArweave, kidFor };
